# Copies of the landing's Contribute and Subscribe sections, for the editions. Regenerate from the landing if those change.
END_CSS = '.secin h2,.arch h2,.sbm h2{font-family:"Literata",Georgia,serif;font-weight:800;font-size:clamp(28px,3vw,38px);line-height:1.1;letter-spacing:-.015em}\n.sbm .kk{display:none}\n.secin h2::before,.arch h2::before,.sbm h2::before{display:block;font:700 11px/1 var(--ui);letter-spacing:.2em;text-transform:uppercase;margin-bottom:10px;color:var(--lc,#b8782e)}\n.sbm h2::before{content:"Contribute"}\n.secin .wrap,.arch .wrap,.sbm .wrap,.svy .wrap{padding-top:80px!important;padding-bottom:80px!important}\n.sbm{background:var(--card)!important;border-top:1px solid var(--rule)!important}\n.nsp .nt{font:600 14px/1.25 var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sbm{overflow:hidden}\n.sbm .wrap{padding-top:56px;padding-bottom:64px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:24px 56px;align-items:center}\n.sbm .art{position:relative;margin:0}\n.sbm .art img{display:block;width:100%;height:auto;filter:drop-shadow(0 18px 28px rgba(29,26,22,.18))}\n.sbm .art figcaption{font:12px var(--ui);color:var(--mute);margin-top:8px;text-align:right}\n.sbm .kk{font:700 12px/1 var(--ui);letter-spacing:.18em;text-transform:uppercase;color:#b8782e;margin:0 0 12px}\n.sbm h2{font-size:clamp(30px,3.6vw,44px);line-height:1.08;margin:0 0 14px}\n.sbm .ld{font-size:17px;line-height:1.55;color:var(--soft);margin:0 0 28px;max-width:46ch}\n.sbtn{display:inline-flex;align-items:center;gap:10px;font:700 19px/1 "Barlow Condensed","Arial Narrow",sans-serif;letter-spacing:.04em;text-transform:uppercase;text-decoration:none;background:#222e4c;color:#f2cfc6;padding:14px 24px;border-radius:3px;transition:transform .2s,box-shadow .2s}\n.sbtn:hover{transform:translateY(-2px);box-shadow:0 8px 18px rgba(0,0,0,.2)}\n.sbtn:focus-visible{outline:2px solid var(--link);outline-offset:3px}\n@media (max-width:860px){.sbm .wrap{grid-template-columns:1fr}.sbm .art{max-width:520px}}\n@media (prefers-reduced-motion:reduce){.thm img,.sbtn,.dl .tg svg{transition:none}}\n.sbc .wrap{display:grid!important;grid-template-columns:1fr!important;justify-items:center;text-align:center;gap:0!important}\n.sbc h2{max-width:22ch;margin:0 auto 18px;text-wrap:balance}\n.sbc .places{font:700 17px/1.6 "Barlow Condensed","Arial Narrow",sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--soft);margin:0 0 28px}\n.sbc .places a{text-decoration:none;color:var(--soft)}\n.sbc .places a:hover{color:var(--c)}\n.sbc .places em{font-style:normal;color:#b8782e;border-bottom:2px dashed #b8782e}\n.sbc .pt{display:block;width:min(260px,70%);height:auto;margin:0 0 26px}\n.sbc .sbr{display:grid;grid-template-columns:230px minmax(0,1fr);gap:34px;align-items:center;width:100%;max-width:900px;margin:0 auto 26px}\n.sbc .sbr .pt{margin:0;width:100%}\n.sbc .nt{position:relative;background:#fffdf6;color:#1d1a16;padding:18px 22px 16px;text-align:left;box-shadow:0 8px 20px rgba(29,26,22,.12);transform:rotate(-.8deg)}\n.sbc .nt p{font:15px/1.55 "Literata",Georgia,serif;margin:0 0 6px}\n.sbc .nt p:last-child{margin:0}\n.sbc .nt::before{content:"";position:absolute;top:-9px;left:50%;width:80px;height:20px;transform:translateX(-50%) rotate(2deg);background:rgba(242,207,198,.85)}\n@media (max-width:700px){.sbc .sbr{grid-template-columns:1fr;gap:20px}.sbc .sbr .pt{max-width:160px;margin:0 auto}}\n.sbc .ckl{width:100%;max-width:1000px;margin:0 0 22px}\n.sbc .meter{height:5px;background:var(--rule);border-radius:3px;overflow:hidden;margin:0 0 14px}\n.sbc .meter i{display:block;height:100%;width:0;background:#222e4c;transition:width .3s}\n.sbc .ckl ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}\n.sbc .ckl label{display:flex;gap:10px;align-items:flex-start;text-align:left;padding:10px 12px;border:1px solid var(--rule);border-radius:4px;cursor:pointer;background:var(--paper);height:100%}\n.sbc .ckl input{width:18px;height:18px;accent-color:#222e4c;margin-top:2px;flex:none}\n.sbc .ckl label:has(input:checked){border-color:#222e4c}\n.sbc .ckl b{display:block;font:600 14.5px var(--ui)}\n.sbc .ckl small{color:var(--mute);font-size:12.5px}\n@media (max-width:860px){.sbc .ckl ul{grid-template-columns:1fr 1fr}}\n@media (max-width:520px){.sbc .ckl ul{grid-template-columns:1fr}}\n.secin h2::before,.arch h2::before,.sbm h2::before{border-top:4px double var(--ink);padding-top:12px;width:60px;margin-left:auto;margin-right:auto;white-space:nowrap;text-align:center;width:auto;display:table}\n.sbm h2::before{margin-left:0}\n.sbc h2::before{margin-left:auto!important;margin-right:auto}\n.sbx .wrap{padding-top:80px;padding-bottom:80px;text-align:center}\n.sbx h2{font-family:"Literata",Georgia,serif;font-weight:800;font-size:clamp(28px,3vw,38px);line-height:1.1;letter-spacing:-.015em;margin:0 0 12px}\n.sbx h2::before{content:"Subscribe";display:table;margin:0 auto 10px;border-top:4px double var(--ink);padding-top:12px;font:700 11px/1 var(--ui);letter-spacing:.2em;text-transform:uppercase;color:#b8782e}\n.sbx .ld{font:17px/1.55 "Literata",serif;color:var(--soft);max-width:48ch;margin:0 auto 26px}\n.sf{display:flex;gap:8px;max-width:520px;margin:0 auto}\n.sf input{flex:1;min-width:0;min-height:50px;border:1.5px solid var(--rule);border-radius:999px;padding:0 20px;font:16px var(--ui);background:var(--card);color:var(--ink)}\n.sf input:focus{outline:2px solid #222e4c;outline-offset:1px}\n.sf button{min-height:50px;padding:0 24px;border:0;border-radius:999px;background:#222e4c;color:#fff;font:600 15px var(--ui);cursor:pointer}\n.sf button:hover{background:#2c3a60}\n.dv{border:0;margin:0 auto 18px;padding:0;display:flex;flex-wrap:wrap;justify-content:center;gap:8px}\n.dv legend{width:100%;font:600 12px var(--ui);letter-spacing:.14em;text-transform:uppercase;color:var(--mute);margin-bottom:10px}\n.dv label{cursor:pointer}\n.dv input{position:absolute;opacity:0}\n.dv span{display:grid;gap:2px;padding:10px 18px;border:1.5px solid var(--rule);border-radius:10px;background:var(--card);text-align:center;min-width:150px}\n.dv b{font:600 15px var(--ui)}\n.dv small{font:12.5px var(--ui);color:var(--mute)}\n.dv input:checked+span{border-color:#222e4c;box-shadow:inset 0 0 0 1px #222e4c}\n.dv input:focus-visible+span{outline:2px solid #222e4c;outline-offset:2px}\n.fine{font:13px var(--ui);color:var(--mute);margin:14px 0 0}\n@media (max-width:600px){.sf{flex-direction:column}.dv span{min-width:0}.dv label{flex:1 1 100%}}\n.sbx{background:var(--paper)}\n.sbm{background:var(--paper)!important}\n@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .dv input:checked+span{border-color:var(--ink);box-shadow:inset 0 0 0 1px var(--ink)}:root:not([data-theme="light"]) .sf button,:root:not([data-theme="light"]) .hsub{background:#f2cfc6;color:#222e4c}}\n:root[data-theme="dark"] .dv input:checked+span{border-color:var(--ink);box-shadow:inset 0 0 0 1px var(--ink)}\n:root[data-theme="dark"] .sf button,:root[data-theme="dark"] .hsub{background:#f2cfc6;color:#222e4c}'
SUB_SECTION = '<section id="subscribe" class="sbx" aria-labelledby="sx-h"><div class="wrap"><h2 id="sx-h">Have the next stories sent to you.</h2><p class="ld">Choose how much arrives at a time.</p><fieldset class="dv"><legend>Send me</legend><label><input type="radio" name="dv" value="1"><span><b>One story</b><small>as each is published</small></span></label><label><input type="radio" name="dv" value="3" checked><span><b>A few stories</b><small>two or three at a time</small></span></label><label><input type="radio" name="dv" value="all"><span><b>The full issue</b><small>four to six stories</small></span></label></fieldset><form class="sf" action="#" onsubmit="return false"><label class="vh" for="em-sub">Email address</label><input id="em-sub" type="email" name="email" autocomplete="email" placeholder="Your email address" required><button type="submit">Subscribe</button></form></div></section>'
